using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class PermissionsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Permissions", "View"); return AdminDataService.GetList("Permissions"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Permissions", "View"); return AdminDataService.GetDefinitionMetadata("Permissions"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Permissions", "Delete"); return AdminDataService.Delete("Permissions", id); } } }
